expand_details.cypher:
MATCH (start:api {name: 'POST /api/v1/stationservice/stations'})
CALL apoc.path.expandConfig(start, {
    sequence: 'api,provides,service',
    minLevel: 0,
    maxLevel: 1,
    bfs: true
})
YIELD path
RETURN path, length(path) AS hops
ORDER BY hops;

